node -e '
const crypto = require("crypto");
const fs = require("fs");
const { execSync } = require("child_process");

const files = [
  "crush.wasm",
  "hls-proxy.js",
  "http-client.js",
  "index.js",
  "package.json",
  "resolver.js",
  "services.json"
];

const ipk = "dist/com.cinejoy.tv_1.0.0_all.ipk";

let allMatch = true;

for (const file of files) {
  const diskPath = `services/com.cinejoy.tv.service/${file}`;
  const diskBuf = fs.readFileSync(diskPath);
  const diskHash = crypto.createHash("sha256").update(diskBuf).digest("hex");

  const ipkBuf = execSync(`ar -p "${ipk}" data.tar.gz | tar -zxf - usr/palm/services/com.cinejoy.tv.service/${file} -O`);
  const ipkHash = crypto.createHash("sha256").update(ipkBuf).digest("hex");

  const match = diskHash === ipkHash;
  console.log(`${file}:`);
  console.log(`  Disk SHA-256: ${diskHash}`);
  console.log(`  IPK  SHA-256: ${ipkHash}`);
  console.log(`  Match: ${match}`);

  if (!match) allMatch = false;
}

if (!allMatch) {
  console.error("FAIL: Hash mismatch detected between disk and IPK!");
  process.exit(1);
} else {
  console.log("\nALL 7 SERVICE FILES ARE 100% BYTE-FOR-BYTE IDENTICAL TO IPK PAYLOAD!");
}
'

