113:     /**
114:      * Auto-spawn and maintain Luna keepalive subscription hook
115:      * Supports:
116:      * 1. webOSTV.service.request / window.webOS.service.request
117:      * 2. window.PalmServiceBridge || window.WebOSServiceBridge
118:      * Maintains persistent subscription to keep on-device proxy daemon alive (Triple-Shield)
119:      */
120:     initLunaKeepalive: function () {
121:       var self = this;
122:       var serviceUri = 'luna://com.cinejoy.tv.service';
123:       var method = 'keepalive';
124: 
125:       // Clear any pending reconnection timer
126:       if (this._lunaReconnectTimer) {
127:         clearTimeout(this._lunaReconnectTimer);
128:         this._lunaReconnectTimer = null;
129:       }
130: 
131:       // Cancel existing bridge prior to reconnecting
132:       if (this.state.lunaBridge) {
133:         try {
134:           if (typeof this.state.lunaBridge.cancel === 'function') {
135:             this.state.lunaBridge.cancel();
136:           }
137:         } catch (_) {}
138:         this.state.lunaBridge = null;
139:       }
140:       if (typeof window !== 'undefined' && window._cinejoyLunaBridge) {
141:         try {
142:           if (typeof window._cinejoyLunaBridge.cancel === 'function') {
143:             window._cinejoyLunaBridge.cancel();
144:           }
145:         } catch (_) {}
146:         window._cinejoyLunaBridge = null;
147:       }
148:       if (this.state.lunaRequest) {
149:         try {
150:           if (typeof this.state.lunaRequest.cancel === 'function') {
151:             this.state.lunaRequest.cancel();
152:           }
153:         } catch (_) {}
154:         this.state.lunaRequest = null;
155:       }
156: 
157:       // Method 1: webOSTV.service.request / window.webOS.service.request if available
158:       var serviceApi = null;
159:       if (typeof window !== 'undefined') {
160:         if (window.webOSTV && window.webOSTV.service && typeof window.webOSTV.service.request === 'function') {
161:           serviceApi = window.webOSTV.service;
162:         } else if (window.webOS && window.webOS.service && typeof window.webOS.service.request === 'function') {
163:           serviceApi = window.webOS.service;
164:         }
165:       }
166: 
167:       if (serviceApi) {
168:         try {
169:           console.log('[CinejoyApp] Registering Luna keepalive via webOSTV.service.request...');
170:           var req = serviceApi.request(serviceUri, {
171:             method: method,
172:             parameters: { subscribe: true },
173:             subscribe: true,
174:             resubscribe: true,
175:             onSuccess: function (res) {
176:               if (self.state.lunaRequest && self.state.lunaRequest !== req) {
177:                 return;
178:               }
179:               self.handleKeepaliveSuccess(res);
180:             },
181:             onFailure: function (err) {
182:               if (self.state.lunaRequest && self.state.lunaRequest !== req) {
183:                 return;
184:               }
185:               self.handleKeepaliveFailure(err);
186:             }
187:           });
188:           this.state.lunaRequest = req;
189:           return req;
190:         } catch (err) {
191:           console.warn('[CinejoyApp] webOSTV.service.request call error:', err);
192:           this.handleKeepaliveFailure(err);
193:           return null;
194:         }
195:       }
196: 
197:       // Method 2: Direct native PalmServiceBridge or WebOSServiceBridge (webOS Chromium WAM)
198:       var Bridge = (typeof window !== 'undefined' && (window.PalmServiceBridge || window.WebOSServiceBridge)) || null;
199:       if (Bridge) {
200:         try {
201:           console.log('[CinejoyApp] Registering Luna keepalive via native PalmServiceBridge / WebOSServiceBridge...');
202:           var bridge = new Bridge();
203:           bridge.onservicecallback = function (msg) {
204:             // Guard against callbacks from an abandoned/replaced bridge
205:             if (bridge.cancelled || (self.state.lunaBridge && self.state.lunaBridge !== bridge)) {
206:               return;
207:             }
208:             try {
209:               var res = typeof msg === 'string' ? JSON.parse(msg) : msg;
210:               if (res && res.returnValue !== false) {
211:                 self.handleKeepaliveSuccess(res);
212:               } else {
213:                 self.handleKeepaliveFailure(res);
214:               }
215:             } catch (e) {
216:               console.warn('[CinejoyApp] Native bridge payload parse error:', e);
217:               self.handleKeepaliveFailure(e);
218:             }
219:           };
220: 
221:           bridge.call(serviceUri + '/' + method, JSON.stringify({ subscribe: true }));
222: 
223:           // Store on window and app state to prevent garbage collection of IPC socket
224:           if (typeof window !== 'undefined') {
225:             window._cinejoyLunaBridge = bridge;
226:           }
227:           this.state.lunaBridge = bridge;
228:           return bridge;
229:         } catch (err) {
230:           console.warn('[CinejoyApp] Native PalmServiceBridge instantiation/call error:', err);
231:           this.handleKeepaliveFailure(err);
232:           return null;
233:         }
234:       }
235: 
236:       // Method 3: Desktop Browser / Node test environment fallback
237:       console.log('[CinejoyApp] Running in standard browser or Node test environment (PalmServiceBridge unavailable).');
238:       return null;
239:     },
