const { JSDOM } = require("jsdom");
const assert = require("assert");

const dom = new JSDOM(`<!DOCTYPE html><html><body>
  <div id="view-search" class="view active">
    <div class="tv-keyboard-container"><button class="key-btn" data-nav="true">A</button></div>
    <div id="search-results-grid"><button class="card-poster" data-nav="true">Card</button></div>
  </div>
  <div id="dialog-a" role="dialog"><button id="btn-a" data-nav="true">A</button></div>
  <div id="dialog-b" role="dialog"><button id="btn-b" data-nav="true">B</button></div>
</body></html>`);

global.window = dom.window;
global.document = dom.window.document;
const SpatialNav = require("./app/js/navigation.js");
SpatialNav.init();

const kb = document.querySelector(".tv-keyboard-container");
const grid = document.querySelector("#search-results-grid");
const dlgA = document.querySelector("#dialog-a");
const dlgB = document.querySelector("#dialog-b");

// Test A: Sequential non-modal trap switching
SpatialNav.trap(kb);
assert.strictEqual(SpatialNav.isTrapped(), true);
SpatialNav.trap(grid);
assert.strictEqual(SpatialNav.isTrapped(), true);
SpatialNav.untrap();
assert.strictEqual(SpatialNav.isTrapped(), false, "Untrap on sequential non-modal should fully clear trap");
console.log("  ✔ Sequential non-modal trap switching verified");

// Test B: Stacked modal dialog trapping
SpatialNav.trap(dlgA);
assert.strictEqual(SpatialNav.isTrapped(), true);
SpatialNav.trap(dlgB);
assert.strictEqual(SpatialNav.isTrapped(), true);
const popped = SpatialNav.untrap();
assert.strictEqual(SpatialNav.isTrapped(), true, "Untrap on stacked modal should restore parent modal trap");
assert.strictEqual(SpatialNav._trapStack.length, 1);
SpatialNav.untrap();
assert.strictEqual(SpatialNav.isTrapped(), false, "Second untrap clears root modal trap");
console.log("  ✔ Stacked modal dialog trapping verified");

SpatialNav.destroy();
'

